grand_totals.body_sql:
SELECT
  'Grand Total' AS grand_total_label,
  (
    COALESCE((
      SELECT SUM(1) FROM (
        SELECT DISTINCT `FLOOR_KEY` AS fk FROM `fac_floor` WHERE `FLOOR_KEY` IS NOT NULL
        UNION ALL
        SELECT DISTINCT `FCLT_FLOOR_KEY` AS fk FROM `fclt_floor` WHERE `FCLT_FLOOR_KEY` IS NOT NULL
      ) AS all_floors
    ),0)
  ) AS grand_total_floors,
  (
    COALESCE((
      SELECT SUM(assignable) FROM (
        SELECT `ASSIGNABLE_AREA` AS assignable FROM `fac_floor` WHERE `ASSIGNABLE_AREA` IS NOT NULL
        UNION ALL
        SELECT `ASSIGNABLE_AREA` AS assignable FROM `fclt_floor` WHERE `ASSIGNABLE_AREA` IS NOT NULL
      ) AS assignables
    ),0)
  ) AS grand_total_assignable_area
